def generate_fibonacci_sequence(num_elements):
    sequence = []
    if num_elements >= 1:
        sequence.append(0)
    if num_elements >= 2:
        sequence.append(1)
    for i in range(2, num_elements):
        sequence.append(sequence[i - 1] + sequence[i - 2])
    return sequence

